window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[299]={"id":"299","numero":299,"titre":"Tumeurs intracrâniennes — HTIC — Hydrocéphalie","objectifs":[{"id":"299-1","rang":"A","rubrique":"Définition","titre":"Connaître les principaux types et localisations des tumeurs intracrâniennes","contenu":"<p>Une <span class=\"kw-def\">tumeur intracrânienne</span> désigne toute prolifération cellulaire développée à l'intérieur de la boîte crânienne. On oppose les <span class=\"kw-def\">tumeurs primitives</span> (nées du système nerveux central ou de ses annexes) aux <span class=\"kw-def\">tumeurs secondaires</span>, ou <span class=\"kw-etio\">métastases</span>, greffe d'un cancer extra-cérébral.</p>\n      <p>Deux repères topographiques structurent tout le raisonnement : l'étage <span class=\"kw-def\">sus-tentoriel</span> (au-dessus de la tente du cervelet) et l'étage <span class=\"kw-def\">sous-tentoriel</span>, ou fosse postérieure. Chez l'<strong>adulte</strong>, les tumeurs sont volontiers <span class=\"kw-imagerie\">sus-tentorielles</span> (<span class=\"kw-chiffre\">80 %</span> des cas) et la <span class=\"kw-etio\">métastase</span> est de loin la plus fréquente. Chez l'<strong>enfant</strong>, la <span class=\"kw-imagerie\">fosse postérieure</span> est touchée dans environ <span class=\"kw-chiffre\">50 %</span> des cas.</p>\n      <table >\n        <thead><tr><th>Type <span class=\"kw-etio\">tumoral</span></th><th>Origine</th><th>Localisation préférentielle</th><th>Caractère</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Métastase</span></td><td>Cancer extra-cérébral (poumon, sein, <span class=\"kw-clinique\">mélanome</span>, rein, digestif)</td><td><span class=\"kw-imagerie\">Sus-tentorielle</span> ; jonction substance grise / blanche ; souvent <span class=\"kw-imagerie\">multiples</span></td><td><span class=\"kw-alerte\">Maligne</span> — 1ʳᵉ cause de tumeur intracrânienne de l'adulte</td></tr>\n          <tr><td><span class=\"kw-etio\">Glioblastome</span></td><td>Astrocytes (lignée gliale)</td><td>Hémisphères sus-tentoriels — lobes frontaux et temporaux</td><td><span class=\"kw-alerte\">Maligne</span> — <span class=\"kw-def\">grade</span> <span class=\"kw-chiffre\">4</span> OMS, 1ᵉʳ gliome de l'adulte</td></tr>\n          <tr><td><span class=\"kw-etio\">Méningiome</span></td><td>Cellules arachnoïdiennes (méninges)</td><td><span class=\"kw-imagerie\">Extra-axial</span> à contact dural : convexité, faux du cerveau, base du crâne</td><td>Bénin dans <span class=\"kw-chiffre\">&gt; 90 %</span> des cas (<span class=\"kw-def\">grade</span> 1 OMS)</td></tr>\n          <tr><td><span class=\"kw-etio\">Schwannome vestibulaire</span> (neurinome du VIII)</td><td>Cellules de Schwann</td><td><span class=\"kw-imagerie\">Angle ponto-cérébelleux</span> ; conduit auditif interne</td><td>Bénin — sporadique ou <span class=\"kw-etio\">NF2</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Adénome hypophysaire</span></td><td>Antéhypophyse</td><td>Région <span class=\"kw-imagerie\">sellaire</span> et suprasellaire</td><td>Bénin — fréquent chez l'adulte</td></tr>\n          <tr><td><span class=\"kw-etio\">Lymphome primitif du SNC</span></td><td><span class=\"kw-bio\">Lymphocytes</span> B</td><td><span class=\"kw-imagerie\">Périventriculaire</span>, corps calleux, noyaux gris centraux</td><td><span class=\"kw-alerte\">Maligne</span> — favorisé par l'immunodépression</td></tr>\n          <tr><td><span class=\"kw-etio\">Médulloblastome</span></td><td>Tumeur embryonnaire</td><td><span class=\"kw-imagerie\">Fosse postérieure</span> — vermis cérébelleux (enfant)</td><td><span class=\"kw-alerte\">Maligne</span> — dissémination méningée précoce</td></tr>\n          <tr><td><span class=\"kw-etio\">Astrocytome pilocytique</span></td><td>Astrocytes</td><td>Hémisphères cérébelleux ; ligne médiane (enfant)</td><td>Bénin — <span class=\"kw-def\">grade</span> <span class=\"kw-chiffre\">1</span> OMS</td></tr>\n          <tr><td><span class=\"kw-etio\">Craniopharyngiome</span></td><td>Reliquats de la poche de Rathke</td><td>Ligne médiane <span class=\"kw-imagerie\">sellaire / suprasellaire</span></td><td>Bénin — au contact de l'hypothalamus</td></tr>\n          <tr><td><span class=\"kw-etio\">Kyste colloïde</span></td><td>Reliquat embryonnaire</td><td><span class=\"kw-imagerie\">Troisième ventricule</span> — foramens de Monro</td><td>Bénin — mais <span class=\"kw-alerte\">risque d'HTIC aiguë</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hémangioblastome</span></td><td>Cellules stromales vasculaires</td><td><span class=\"kw-imagerie\">Fosse postérieure</span> — cervelet, tronc</td><td>Bénin — sporadique ou maladie de <span class=\"kw-etio\">von Hippel-Lindau</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Épendymome</span></td><td>Épendymocytes</td><td><span class=\"kw-imagerie\">Intraventriculaire</span> — V4 (enfant), sus-tentoriel (adulte)</td><td>Bénin (<span class=\"kw-def\">grade</span> 1-2) — rarement malin (<span class=\"kw-chiffre\">grade 3</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>📌 Adulte <span class=\"kw-bio\">vs</span> enfant.</strong> Adulte : métastases ≫ glioblastome &gt; méningiome ≈ adénome hypophysaire &gt; lymphome, volontiers sus-tentoriels. <br>Enfant : médulloblastome, astrocytome pilocytique, gliome du tronc, craniopharyngiome — la fosse postérieure est beaucoup plus souvent touchée que chez l'adulte.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux · 297 — Cancer de l'enfant · 309 — Tumeurs du poumon · 311 — Tumeur rénale</em></p>","frequence":3},{"id":"299-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition des tumeurs primitives intracrâniennes : système nerveux central et annexes","contenu":"<p>Une <span class=\"kw-def\">tumeur primitive intracrânienne</span> est une prolifération cellulaire née <strong>à l'intérieur du crâne</strong>, développée à partir des tissus du <span class=\"kw-def\">système nerveux central</span> (SNC) ou de ses <span class=\"kw-def\">annexes</span>. Elle s'oppose à la <span class=\"kw-def\">tumeur secondaire</span> (<span class=\"kw-etio\">métastase</span>) qui correspond à la greffe intracrânienne d'un cancer extra-cérébral.</p>\n      <p>Le <span class=\"kw-def\">TNM n'est pas applicable</span> aux tumeurs primitives du SNC : la <span class=\"kw-def\">classification OMS 2021</span> les gradue de <span class=\"kw-chiffre\">1 à 4</span> selon leur agressivité, en croisant <span class=\"kw-def\">critères histologiques</span> (cellule d'origine) et <span class=\"kw-bio\">marqueurs biomoléculaires</span>.</p>\n      <table >\n        <thead><tr><th>Compartiment</th><th>Tissu d'origine</th><th>Tumeur primitive correspondante</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"3\">Système nerveux central</td><td>Astrocytes</td><td><span class=\"kw-etio\">Astrocytomes</span> (dont glioblastome)</td></tr>\n          <tr><td>Oligodendrocytes</td><td><span class=\"kw-etio\">Oligodendrogliomes</span></td></tr>\n          <tr><td>Épendymocytes ; cellules embryonnaires</td><td><span class=\"kw-etio\">Épendymomes</span> ; <span class=\"kw-etio\">médulloblastomes</span></td></tr>\n          <tr><td rowspan=\"4\">Annexes du SNC</td><td>Méninges (arachnoïde)</td><td><span class=\"kw-etio\">Méningiomes</span></td></tr>\n          <tr><td>Gaines nerveuses (cellules de Schwann)</td><td><span class=\"kw-etio\">Neurinomes</span> (schwannomes)</td></tr>\n          <tr><td>Axe hypothalamo-hypophysaire ; reliquats embryonnaires</td><td><span class=\"kw-etio\">Adénomes hypophysaires</span> ; <span class=\"kw-etio\">craniopharyngiomes</span> ; kyste colloïde</td></tr>\n          <tr><td>Tissus vasculaires ; <span class=\"kw-bio\">lymphocytes</span> B</td><td><span class=\"kw-etio\">Hémangioblastomes</span> ; <span class=\"kw-etio\">lymphomes primitifs du SNC</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bénin ou malin ?</strong> La distinction est importante mais ne préjuge pas de la <span class=\"kw-def\">morbidité</span> :</p>\n      <ul>\n        <li><strong>Tumeurs habituellement bénignes</strong> : méningiomes typiques, schwannomes, adénomes hypophysaires, astrocytome pilocytique — croissance lente, bien circonscrites.</li>\n        <li><strong>Tumeurs malignes</strong> : gliomes de haut <span class=\"kw-def\">grade</span>, lymphomes, médulloblastomes — infiltrantes, <span class=\"kw-clinique\">évolution</span> rapide.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>📌 Bénin n'est pas anodin.</strong> Une tumeur histologiquement bénigne peut rester <span class=\"kw-alerte\">menaçante par son effet de masse</span> (<span class=\"kw-alerte\">HTIC</span>, engagement) ou par sa localisation chirurgicalement inaccessible.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0},{"id":"299-3","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs cérébrales","contenu":"<p>La <span class=\"kw-def\">classification OMS 2021</span> des tumeurs du SNC repose sur deux piliers : le <span class=\"kw-def\">diagnostic histologique</span> (cellule d'origine) et les <span class=\"kw-bio\">marqueurs biomoléculaires</span> (altérations cytogénétiques et moléculaires), ces derniers contribuant au grading, au <span class=\"kw-def\">pronostic</span> et aux décisions thérapeutiques.</p>\n      <table >\n        <thead><tr><th>Type histologique</th><th>Origine cellulaire</th><th><span class=\"kw-def\">Grade</span> OMS</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Astrocytome pilocytique</span></td><td>Astrocytes</td><td><span class=\"kw-chiffre\">1</span></td><td>Enfant ; cérébelleux, bien circonscrit, composante kystique ; guérison si <span class=\"kw-ttt\">exérèse</span> complète</td></tr>\n          <tr><td><span class=\"kw-etio\">Gliome diffus de bas grade</span></td><td>Astrocytes / oligodendrocytes</td><td><span class=\"kw-chiffre\">2</span></td><td>Adulte jeune (<span class=\"kw-chiffre\">30-40 ans</span>) ; <span class=\"kw-clinique\">épilepsie</span> révélatrice ; pas de rehaussement ; calcifications (oligodendrogliome)</td></tr>\n          <tr><td><span class=\"kw-etio\">Gliome anaplasique</span></td><td>Astrocytes / oligodendrocytes</td><td><span class=\"kw-chiffre\">3</span></td><td><span class=\"kw-chiffre\">30-50 ans</span> ; <span class=\"kw-radio\">prise de contraste</span>, <span class=\"kw-radio\">néoangiogenèse</span> ; <span class=\"kw-radio\">pas de nécrose</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Glioblastome</span></td><td>Astrocytes</td><td><span class=\"kw-chiffre\">4</span></td><td><span class=\"kw-chiffre\">50-70 ans</span> ; <span class=\"kw-radio\">nécrose</span>, <span class=\"kw-radio\">contraste hétérogène</span> ; <span class=\"kw-bio\">IDH</span> non muté de novo</td></tr>\n          <tr><td><span class=\"kw-etio\">Méningiome</span></td><td>Cellules arachnoïdiennes</td><td><span class=\"kw-chiffre\">1</span> (&gt; <span class=\"kw-chiffre\">90 %</span>), 2, 3</td><td>Femme <span class=\"kw-chiffre\">50-70 ans</span> ; extra-axial, <span class=\"kw-radio\">queue durale</span> ; <span class=\"kw-ci\">hormonodépendant</span> (progestatifs)</td></tr>\n          <tr><td><span class=\"kw-etio\">Métastase</span></td><td>Cancer extra-cérébral</td><td>— (<span class=\"kw-def\">grade</span> du primitif)</td><td>Tumeur intracrânienne la plus fréquente de l'adulte ; multiples, <span class=\"kw-radio\">image en cocarde</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Médulloblastome</span></td><td>Tumeur embryonnaire</td><td>Haut <span class=\"kw-def\">grade</span></td><td>Enfant (<span class=\"kw-chiffre\">70 %</span> avant <span class=\"kw-chiffre\">20 ans</span>) ; vermis cérébelleux ; <span class=\"kw-alerte\">dissémination méningée</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Lymphome primitif du SNC</span></td><td><span class=\"kw-bio\">Lymphocyte</span> B (DLBCL, <span class=\"kw-chiffre\">90 %</span>)</td><td>—</td><td>Immunodépression (<span class=\"kw-etio\">VIH</span>, greffe) ou immunocompétent ~<span class=\"kw-chiffre\">60 ans</span> ; <span class=\"kw-radio\">restriction de diffusion</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Schwannome</span> (neurinome)</td><td>Cellules de Schwann</td><td>Bénin</td><td>Nerf vestibulaire ++ ; sporadique ou <span class=\"kw-etio\">NF2</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Hémangioblastome</span></td><td>Cellules stromales vasculaires</td><td>Bénin</td><td>Fosse postérieure ; <span class=\"kw-etio\">von Hippel-Lindau</span> ; polyglobulie (sécrétion d'EPO)</td></tr>\n          <tr><td><span class=\"kw-etio\">Craniopharyngiome</span></td><td>Reliquats de la poche de Rathke</td><td>Bénin</td><td>Région sellaire ; puberté précoce et <span class=\"kw-bio\">TCA</span> chez l'enfant</td></tr>\n          <tr><td><span class=\"kw-etio\">Épendymome</span></td><td>Épendymocytes</td><td><span class=\"kw-chiffre\">1-2</span> (rarement 3)</td><td>Intraventriculaire ; <span class=\"kw-radio\">rosettes péri-épendymaires</span> ; <span class=\"kw-def\">pronostic</span> sévère chez l'enfant &lt;<span class=\"kw-chiffre\"> 5 ans</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Kyste colloïde</span></td><td>Reliquat embryonnaire</td><td>Bénin</td><td>Troisième ventricule ; <span class=\"kw-radio\">hyperdense en TDM</span>, <span class=\"kw-radio\">hyperT1 spontané</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Biomarqueurs des gliomes diffus de l'adulte</strong> (recherchés sur le tissu <span class=\"kw-etio\">tumoral</span>, valeur diagnostique et pronostique) :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Mutation IDH</span> — facteur de bon <span class=\"kw-def\">pronostic</span> ; absente dans le glioblastome de novo.</li>\n        <li><span class=\"kw-bio\">Codélétion 1p/19q</span> — signe l'<span class=\"kw-etio\">oligodendrogliome</span> ; meilleure chimiosensibilité.</li>\n        <li><span class=\"kw-bio\">Hyperméthylation du promoteur MGMT</span> — meilleure réponse au <span class=\"kw-ttt\">témozolomide</span> dans le glioblastome.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/who-classification-of-cns-tumours-1","label":"Radiopaedia : Who classification of cns tumours 1"},{"href":"https://radiopaedia.org/articles/pilocytic-astrocytoma","label":"Radiopaedia : Pilocytic astrocytoma"},{"href":"https://radiopaedia.org/articles/oligodendroglioma","label":"Radiopaedia : Oligodendroglioma"},{"href":"https://radiopaedia.org/articles/oligoastrocytoma-historical","label":"Radiopaedia : Oligoastrocytoma historical"},{"href":"https://radiopaedia.org/articles/glioblastoma-idh-wildtype","label":"Radiopaedia : Glioblastoma idh wildtype"},{"href":"https://radiopaedia.org/articles/meningioma","label":"Radiopaedia : Meningioma"},{"href":"https://radiopaedia.org/articles/medulloblastoma","label":"Radiopaedia : Medulloblastoma"},{"href":"https://radiopaedia.org/articles/lymphomas-of-the-central-nervous-system","label":"Radiopaedia : Lymphomas of the central nervous system"},{"href":"https://radiopaedia.org/articles/vestibular-schwannoma","label":"Radiopaedia : Vestibular schwannoma"},{"href":"https://radiopaedia.org/articles/haemangioblastoma-central-nervous-system-2","label":"Radiopaedia : Haemangioblastoma central nervous system 2"},{"href":"https://radiopaedia.org/articles/ependymoma","label":"Radiopaedia : Ependymoma"},{"href":"https://radiopaedia.org/articles/craniopharyngioma-historical","label":"Radiopaedia : Craniopharyngioma historical"},{"href":"https://radiopaedia.org/articles/colloid-cyst-of-the-third-ventricle","label":"Radiopaedia : Colloid cyst of the third ventricle"}]},{"id":"299-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des différents types tumeurs primitives intracrâniennes","contenu":"<p>Les tumeurs intracrâniennes sont <strong>rares</strong> : environ <span class=\"kw-chiffre\">13 000</span> nouveaux cas par an en France, avec une <span class=\"kw-def\">incidence</span> en augmentation pour des raisons mal identifiées. Il existe une prédominance <strong>masculine</strong> pour tous les types histologiques, <strong>sauf le <span class=\"kw-etio\">méningiome</span></strong> (prédominance féminine).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Données épidémiologiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Adulte</strong></td><td><strong>Fréquence :</strong> tumeurs volontiers <span class=\"kw-imagerie\">sus-tentorielles</span> (<span class=\"kw-chiffre\">80 %</span>) ; <br><strong>Ordre décroissant :</strong> <span class=\"kw-etio\">métastases</span> (7× plus fréquentes que les primitives) ; <span class=\"kw-etio\">gliomes</span> dont le glioblastome (<span class=\"kw-chiffre\">8</span>/100 000/an) ; <span class=\"kw-etio\">méningiome</span> (<span class=\"kw-chiffre\">5</span>/100 000/an) ; <span class=\"kw-etio\">adénome hypophysaire</span> (<span class=\"kw-chiffre\">5</span>/100 000/an) ; <span class=\"kw-etio\">lymphome primitif</span> (<span class=\"kw-chiffre\">3</span>/100 000/an)</td></tr>\n          <tr><td><strong>Enfant</strong></td><td><strong>Poids :</strong> <span class=\"kw-chiffre\">20-25 %</span> des cancers de l'enfant = cancer solide le plus fréquent ; <br><strong><span class=\"kw-def\">Incidence</span> :</strong> 4× inférieure à l'adulte (<span class=\"kw-chiffre\">4</span>/100 000/an, soit ~400 cas/an avant <span class=\"kw-chiffre\">15 ans</span>) ; <br><strong>Topographie :</strong> sus-tentorielle (<span class=\"kw-chiffre\">50 %</span> — astrocytome pilocytique, craniopharyngiome, gliome des voies optiques, région pinéale) ; sous-tentorielle (<span class=\"kw-chiffre\">50 %</span> — médulloblastome, gliome du tronc, astrocytome pilocytique cérébelleux)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Phacomatoses</strong> — prédispositions génétiques (rang C), rares mais à connaître :</p>\n      <table >\n        <thead><tr><th>Phacomatose</th><th>Gène</th><th>Tumeurs intracrâniennes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">NF1</span> (von Recklinghausen)</td><td>NF1 (chr. 17)</td><td>Gliome des voies optiques (&lt;<span class=\"kw-chiffre\"> 6 ans</span>), gliomes cérébraux, neurofibromes</td></tr>\n          <tr><td><span class=\"kw-etio\">NF2</span></td><td>NF2 (22q12)</td><td>Schwannome vestibulaire bilatéral du sujet jeune, méningiomes multiples, épendymomes</td></tr>\n          <tr><td><span class=\"kw-etio\">von Hippel-Lindau</span></td><td>VHL (3p25)</td><td>Hémangioblastome cérébelleux ; associé : phéochromocytome, <span class=\"kw-clinique\">carcinome</span> rénal à cellules claires</td></tr>\n          <tr><td><span class=\"kw-etio\">Sclérose tubéreuse de Bourneville</span></td><td>TSC1 / TSC2</td><td>Astrocytome sous-épendymaire à cellules géantes, tubers corticaux (épilepsie)</td></tr>\n          <tr><td><span class=\"kw-etio\">Li-Fraumeni</span></td><td>TP53</td><td>Tumeurs cérébrales diverses (glioblastome, médulloblastome) — transmission autosomique dominante</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres facteurs favorisants :</strong></p>\n      <ul>\n        <li><strong>Hormonal :</strong> le <span class=\"kw-etio\">méningiome</span> exprime des récepteurs aux œstrogènes et à la progestérone ; cas induits par l'<span class=\"kw-ci\">acétate de cyprotérone</span> (régression à l'arrêt) ; association classique <span class=\"kw-etio\">méningiome</span> ↔ <span class=\"kw-etio\">cancer du sein</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Irradiation</span> :</strong> méningiomes et lymphomes peuvent être <span class=\"kw-etio\">radio-induits</span>.</li>\n        <li><strong>Non prouvé :</strong> imputabilité probable du tabac et de certains pesticides ; téléphone portable non démontré.</li>\n      </ul>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/tuberous-sclerosis","label":"Radiopaedia : Tuberous sclerosis"},{"href":"https://radiopaedia.org/articles/von-hippel-lindau-disease-5","label":"Radiopaedia : Von hippel lindau disease 5"},{"href":"https://radiopaedia.org/articles/neurofibromatosis-type-1","label":"Radiopaedia : Neurofibromatosis type 1"},{"href":"https://radiopaedia.org/articles/neurofibromatosis-type-2-3","label":"Radiopaedia : Neurofibromatosis type 2 3"},{"href":"https://radiopaedia.org/articles/li-fraumeni-syndrome-2","label":"Radiopaedia : Li fraumeni syndrome 2"}]},{"id":"299-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","contenu":"<p>Une tumeur intracrânienne se révèle par <strong>quatre grands tableaux cliniques</strong>, isolés ou associés. Aucun n'est spécifique : c'est leur installation <span class=\"kw-clinique\">progressive</span> ou leur association qui doit alerter.</p>\n      <table >\n        <thead><tr><th>Tableau</th><th>Signes</th><th>Mécanisme</th><th>Topographie évocatrice</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Syndrome d'HTIC</span></td><td><span class=\"kw-clinique\">Céphalées</span> matinales, croissantes, rebelles aux <span class=\"kw-ttt\">antalgiques</span> ; <span class=\"kw-clinique\">vomissements en jet</span> ; <span class=\"kw-clinique\">œdème papillaire</span> au <span class=\"kw-imagerie\">fond d'œil</span> ; <span class=\"kw-clinique\">diplopie</span> (paralysie du VI)</td><td>Effet de <span class=\"kw-clinique\">masse</span>, <span class=\"kw-clinique\">œdème</span> péri-<span class=\"kw-etio\">tumoral</span>, hydrocéphalie</td><td>Toute tumeur ; surtout <span class=\"kw-imagerie\">fosse postérieure</span> et tumeurs intraventriculaires</td></tr>\n          <tr><td><span class=\"kw-clinique\">Crise d'épilepsie</span></td><td>Crise <span class=\"kw-clinique\">focale</span> ou secondairement généralisée ; révèle <span class=\"kw-chiffre\">20-40 %</span> des tumeurs</td><td>Irritation du cortex cérébral par la tumeur</td><td>Tumeur au contact du cortex ; gliome de bas <span class=\"kw-def\">grade</span>, méningiome</td></tr>\n          <tr><td><span class=\"kw-clinique\">Déficit neurologique focal</span></td><td>Déficit moteur ou sensitif, <span class=\"kw-clinique\">aphasie</span>, <span class=\"kw-clinique\">hémianopsie</span>, <span class=\"kw-clinique\">ataxie cérébelleuse</span>, atteinte de nerfs crâniens — installation progressive « en tache d'huile »</td><td>Compression ou <span class=\"kw-ttt\">infiltration</span> du parenchyme (aggravée par l'<span class=\"kw-clinique\">œdème</span>)</td><td><span class=\"kw-alerte\">Localisateur</span> de la région cérébrale atteinte</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles cognitifs et comportementaux</span></td><td><span class=\"kw-clinique\">Syndrome frontal</span>, troubles mnésiques, ralentissement, modification du caractère ; <span class=\"kw-clinique\">syndrome confusionnel</span> ou démentiel progressif</td><td>Lésions multiples ou étendues</td><td>Métastases, gliome infiltrant, lymphome — surtout sujet âgé</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Deux tableaux plus spécifiques :</strong></p>\n      <ul>\n        <li><strong>Anomalies endocriniennes :</strong> <span class=\"kw-etio\">adénome hypophysaire</span> ; <span class=\"kw-etio\">craniopharyngiome</span> (puberté précoce, troubles du comportement alimentaire) ; <span class=\"kw-clinique\">diabète insipide</span> par <span class=\"kw-clinique\">lésion</span> de la post-hypophyse.</li>\n        <li><strong>Méningite <span class=\"kw-etio\">tumorale</span> :</strong> atteinte de plusieurs <span class=\"kw-clinique\">nerfs crâniens</span>, atteinte pluriradiculaire, manifestations encéphalitiques fluctuantes, <span class=\"kw-alerte\">syndrome méningé</span> en arrière-plan.</li>\n      </ul>\n      <p><strong>Signes selon la topographie :</strong></p>\n      <ul>\n        <li><strong>Fosse postérieure :</strong> ataxie, troubles de l'équilibre, atteinte des nerfs crâniens bas.</li>\n        <li><strong>Région sellaire :</strong> trouble du champ visuel (quadranopsie bitemporale), troubles endocriniens.</li>\n        <li><strong>Lobe frontal :</strong> <span class=\"kw-clinique\">syndrome frontal</span>, troubles de la personnalité.</li>\n        <li><strong>Lobe temporal :</strong> aphasie (hémisphère dominant), troubles mnésiques, épilepsie temporale.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>📌 Particularités de l'enfant.</strong> Augmentation du <span class=\"kw-clinique\">périmètre crânien</span>, <span class=\"kw-clinique\">fontanelle bombée</span>, <span class=\"kw-clinique\">regard en coucher de soleil</span>, <span class=\"kw-clinique\">torticolis</span> persistant, <span class=\"kw-clinique\">vomissements</span> matinaux pseudo-digestifs, <span class=\"kw-clinique\">fléchissement scolaire</span> — présentations souvent frustes et trompeuses.</div>\n      <div class=\"callout callout-danger\"><strong>⚠️ Dogme à retenir.</strong> Toute <span class=\"kw-alerte\">première crise d'épilepsie chez un adulte</span> impose une <span class=\"kw-imagerie\">imagerie cérébrale</span> à la recherche d'une tumeur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span> · 91 — Déficit neuro récent · 105 — Epilepsie · 108 — Confusion, démence du sujet âgé · 102 — Diplopie</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/leptomeningeal-metastases","label":"Radiopaedia : Leptomeningeal metastases"}]},{"id":"299-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d'exploration en imagerie devant une tumeur intracrânienne de l'adulte","contenu":"<p>Le diagnostic des tumeurs intracrâniennes repose sur l'<strong>analyse de l'imagerie</strong> (<span class=\"kw-imagerie\">IRM</span> multimodale), complétée par les <span class=\"kw-def\">critères histologiques</span> et les <span class=\"kw-bio\">marqueurs biomoléculaires</span>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Place et apport</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">IRM cérébrale</span> sans puis avec gadolinium</td><td><strong>Examen de référence</strong>, réalisée même si un <span class=\"kw-imagerie\">TDM</span> a précédé. <br><strong>Séquences :</strong> T1, T2/FLAIR (<span class=\"kw-clinique\">œdème</span>), T2* (saignement), diffusion, T1 après injection (<span class=\"kw-alerte\">rupture</span> de la barrière hémato-encéphalique). <br><strong>Multimodale :</strong> perfusion (<span class=\"kw-radio\">néoangiogenèse</span>), spectroscopie (prolifération), BOLD fonctionnel (cartographie du langage et de la motricité).</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM cérébrale</span> sans puis avec injection</td><td>Souvent réalisée <strong>en <span class=\"kw-alerte\">urgence</span> en 1ʳᵉ intention</strong> mais <span class=\"kw-alerte\">ne remplace pas l'IRM</span>. <br><strong>Indications :</strong> urgence (<span class=\"kw-alerte\">HTIC</span> aiguë, suspicion d'engagement, troubles de la vigilance) ; recherche de <span class=\"kw-radio\">calcifications</span> ; <span class=\"kw-ci\">contre-indication</span> à l'<span class=\"kw-imagerie\">IRM</span>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Sémiologie radiologique caractéristique selon le type <span class=\"kw-etio\">tumoral</span> :</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Aspect en imagerie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Métastase</span></td><td><span class=\"kw-radio\">Multiples</span>, prise de contraste en <span class=\"kw-radio\">cocarde</span> (centre nécrotique + rehaussement périphérique), <span class=\"kw-clinique\">œdème</span> péri-lésionnel marqué ; <span class=\"kw-radio\">lâcher de ballons</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Glioblastome</span></td><td>Rehaussement <span class=\"kw-radio\">hétérogène en anneau irrégulier</span>, <span class=\"kw-radio\">nécrose</span> centrale, <span class=\"kw-clinique\">œdème</span>, effet de <span class=\"kw-clinique\">masse</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Gliome de bas grade</span></td><td><span class=\"kw-radio\">HypoT1, hyperT2/FLAIR</span>, <span class=\"kw-alerte\">absence de rehaussement</span> ; calcifications (oligodendrogliome) ; perfusion sans <span class=\"kw-radio\">néoangiogenèse</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Méningiome</span></td><td>Tumeur <span class=\"kw-radio\">extra-axiale</span> à base d'implantation durale, <span class=\"kw-radio\">rehaussement homogène</span>, « <span class=\"kw-radio\">queue durale</span> », calcifications fréquentes</td></tr>\n          <tr><td><span class=\"kw-etio\">Schwannome vestibulaire</span></td><td>Angle ponto-cérébelleux, élargissement du conduit auditif interne, <span class=\"kw-radio\">rehaussement homogène</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Lymphome primitif du SNC</span></td><td>Rehaussement intense « cotonneux », <span class=\"kw-radio\">restriction de diffusion</span>, périventriculaire, faible effet de <span class=\"kw-clinique\">masse</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Méningite tumorale</span> (carcinomatose leptoméningée)</td><td><span class=\"kw-imagerie\">IRM cérébrale</span> <strong>et médullaire</strong> : prises de contraste des <span class=\"kw-radio\">méninges</span>, péri-ventriculaires, nerfs crâniens, région thoraco-lombaire ; <span class=\"kw-bio\">LCS</span> : <span class=\"kw-bio\">hyperprotéinorachie</span> <span class=\"kw-chiffre\">&gt; 1 g/L</span> + <span class=\"kw-bio\">hypoglycorachie</span>, cytologie <span class=\"kw-etio\">tumorale</span> (PL à répéter <span class=\"kw-chiffre\">≥ 3</span>×)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Diagnostics différentiels piégeants :</strong> <span class=\"kw-imagerie\">AVC ischémique</span> ancien (prise de contraste par <span class=\"kw-alerte\">rupture</span> de la barrière), <span class=\"kw-imagerie\">hématome intra-parenchymateux</span> (refaire l'<span class=\"kw-imagerie\">IRM</span> à <span class=\"kw-chiffre\">4-6 semaines</span>), <span class=\"kw-etio\">abcès</span> (paroi fine, diffusion : centre en <span class=\"kw-radio\">hypersignal avec ADC bas</span>).</p>\n      <div class=\"callout callout-info\"><strong>📌 Place de l'<span class=\"kw-bio\">histologie</span>.</strong> Le diagnostic de certitude repose sur la <span class=\"kw-bio\">biopsie stéréotaxique</span> ou l'<span class=\"kw-ttt\">exérèse</span> chirurgicale — sauf métastase d'un cancer primitif connu, où l'<span class=\"kw-imagerie\">IRM</span> peut suffire. Aucune <span class=\"kw-ttt\">chimiothérapie</span> n'est possible sans matériel <span class=\"kw-etio\">tumoral</span> analysé.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0},{"id":"299-7","rang":"A","rubrique":"Diagnostic positif","titre":"Décrire la recherche systématique de cancer primitif à effectuer devant une métastase cérébrale","contenu":"<p>La <span class=\"kw-etio\">métastase cérébrale</span> est la <strong>1ʳᵉ cause de tumeur intracrânienne de l'adulte</strong>. Elle est <span class=\"kw-alerte\">révélatrice</span> du cancer dans environ <span class=\"kw-chiffre\">20 %</span> des cas, et aucun primitif n'est retrouvé dans <span class=\"kw-chiffre\">10 %</span> des cas.</p>\n      <p><strong>Cancers primitifs pourvoyeurs</strong> — moyen mnémotechnique <span class=\"kw-def\">PPRSC</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Poumon</span> (cancer bronchique) — le primitif le plus fréquent.</li>\n        <li><span class=\"kw-etio\">Peau</span> — <span class=\"kw-clinique\">mélanome</span> (fort tropisme cérébral, métastases volontiers hémorragiques).</li>\n        <li><span class=\"kw-etio\">Sein</span> — chez la femme.</li>\n        <li><span class=\"kw-etio\">Rein</span> — <span class=\"kw-clinique\">carcinome</span> à cellules claires (métastases hémorragiques).</li>\n        <li><span class=\"kw-etio\">Côlon</span> et cancers digestifs — plus rarement.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Étape du bilan</th><th>Examens / cible recherchée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Interrogatoire</span></td><td>Antécédents carcinologiques personnels et familiaux, <span class=\"kw-etio\">tabagisme</span>, exposition professionnelle, signes généraux (<span class=\"kw-clinique\">amaigrissement</span>, asthénie)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Examen clinique complet</span></td><td>Palpation mammaire, aires ganglionnaires, examen cutané (<span class=\"kw-clinique\">mélanome</span>), auscultation pulmonaire, examen abdominal et ORL</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Imagerie d'extension</span></td><td><span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvienne</span> injectée ± <span class=\"kw-imagerie\">TEP-TDM</span> au 18F-FDG (recherche du primitif et d'autres localisations)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Examens orientés</span></td><td>Femme : <span class=\"kw-imagerie\">mammographie</span> ± <span class=\"kw-imagerie\">échographie</span> ; tabagique : <span class=\"kw-imagerie\">fibroscopie bronchique</span> ; <span class=\"kw-clinique\">mélanome</span> : examen dermatologique du corps entier</td></tr>\n          <tr><td><span class=\"kw-bio\">Biologie</span></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">LDH</span> ; <span class=\"kw-bio\">marqueurs tumoraux</span> orientés selon le contexte</td></tr>\n          <tr><td><span class=\"kw-bio\">Histologie</span></td><td><span class=\"kw-ttt\">Biopsie</span> périphérique si primitif identifié (plus accessible) ; sinon <span class=\"kw-bio\">biopsie stéréotaxique cérébrale</span> avec <span class=\"kw-bio\">immunohistochimie</span> d'orientation</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>📌 Quand l'<span class=\"kw-imagerie\">IRM</span> suffit-elle ?</strong> Si le cancer primitif est connu et évolutif, le diagnostic de métastase peut être retenu sur les caractéristiques de l'<span class=\"kw-imagerie\">IRM</span>. Si le primitif est inconnu, l'<span class=\"kw-bio\">histologie</span> est nécessaire.</div>\n      <div class=\"callout callout-danger\"><strong>⚠️ Métastase révélatrice par <span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">hémorragique</span>.</strong> Une métastase de <span class=\"kw-etio\">mélanome</span> ou de <span class=\"kw-etio\">rein</span> peut se révéler par un saignement intracérébral — refaire l'<span class=\"kw-imagerie\">IRM</span> à distance de l'épisode hémorragique pour démasquer la <span class=\"kw-clinique\">lésion</span>. La décision thérapeutique se prend en <span class=\"kw-ttt\">RCP neuro-oncologique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 311 — Tumeur rénale · 295 — Prise en charge d'un malade cancéreux · 297 — Cancer de l'enfant</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/brain-metastases","label":"Radiopaedia : Brain metastases"}]},{"id":"299-8","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","contenu":"<p>Chez un patient porteur d'une tumeur, deux complications dominent l'<span class=\"kw-alerte\">urgence</span> : le <span class=\"kw-alerte\">syndrome d'HTIC</span> (<span class=\"kw-alerte\">menace</span> vitale) et la <span class=\"kw-alerte\">crise d'épilepsie</span>.</p>\n      <p><strong>I. Syndrome d'<span class=\"kw-alerte\">HTIC</span> sur tumeur cérébrale</strong></p>\n      <p>L'<span class=\"kw-def\">HTIC</span> se définit par une pression intracrânienne (<span class=\"kw-def\">PIC</span>) <span class=\"kw-chiffre\">&gt; 15 mmHg</span> (normale : <span class=\"kw-chiffre\">5-15 mmHg</span>) ; au-delà de <span class=\"kw-chiffre\">20 mmHg</span>, elle est franchement pathologique. Selon la <span class=\"kw-def\">loi de Monro-Kelli</span>, le volume intracrânien est constant : V[parenchyme] + V[<span class=\"kw-bio\">LCS</span>] + V[sang] = constante. Toute augmentation d'un compartiment épuise les mécanismes compensateurs puis fait grimper la PIC. La <span class=\"kw-def\">PPC</span> (pression de perfusion cérébrale) = <span class=\"kw-def\">PAM</span> − PIC, et doit être maintenue <span class=\"kw-chiffre\">&gt; 70 mmHg</span>.</p>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 392\" role=\"img\" aria-label=\"Schéma de la loi de Monro-Kelli et de la courbe de Langfitt. L'enceinte crânienne est inextensible et contient trois compartiments de volume constant, environ 1400 millilitres : le parenchyme cérébral, le liquide cérébro-spinal et le volume sanguin. Quand une tumeur ajoute du volume, les mécanismes compensateurs chassent d'abord le liquide cérébro-spinal et le sang veineux : la pression intracrânienne reste stable, c'est la phase de compensation ou plateau. Une fois ces mécanismes dépassés, la courbe pression-volume de Langfitt devient exponentielle : une faible augmentation de volume entraîne une élévation majeure de la pression intracrânienne, c'est la phase de décompensation, avec une PIC supérieure à 20 millimètres de mercure synonyme d'HTIC. La pression de perfusion cérébrale est égale à la pression artérielle moyenne moins la pression intracrânienne, et doit rester supérieure à 70 millimètres de mercure.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"20\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Enceinte crânienne inextensible — V constant (≈<span class=\"kw-chiffre\"> 1400 mL</span>)</text>\n          <rect class=\"fb-grey\" x=\"40\" y=\"30\" width=\"480\" height=\"40\" rx=\"6\"/>\n          <rect class=\"fb-purple\" x=\"44\" y=\"34\" width=\"300\" height=\"32\" rx=\"4\"/>\n          <text class=\"tx-purple\" x=\"194\" y=\"54\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Parenchyme cérébral</text>\n          <rect class=\"fb-teal\" x=\"348\" y=\"34\" width=\"100\" height=\"32\" rx=\"4\"/>\n          <text class=\"tx-teal\" x=\"398\" y=\"54\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\"><span class=\"kw-bio\">LCS</span></text>\n          <rect class=\"fb-red\" x=\"452\" y=\"34\" width=\"64\" height=\"32\" rx=\"4\"/>\n          <text class=\"tx-red\" x=\"484\" y=\"54\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Sang</text>\n          <line class=\"ln\" x1=\"280\" y1=\"72\" x2=\"280\" y2=\"90\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,96 275,88 285,88\"/>\n          <rect class=\"fb-amber\" x=\"110\" y=\"98\" width=\"340\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"116\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Tumeur / <span class=\"kw-clinique\">œdème</span> / hémorragie ajoute du volume</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"132\" text-anchor=\"middle\" font-size=\"10.5\">→ un compartiment augmente</text>\n          <line class=\"ln\" x1=\"280\" y1=\"138\" x2=\"280\" y2=\"154\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"160\" y1=\"154\" x2=\"400\" y2=\"154\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"160\" y1=\"154\" x2=\"160\" y2=\"170\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"160,176 155,168 165,168\"/>\n          <line class=\"ln\" x1=\"400\" y1=\"154\" x2=\"400\" y2=\"170\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"400,176 395,168 405,168\"/>\n          <rect class=\"fb-ok\" x=\"20\" y=\"178\" width=\"280\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Compensation (plateau)</text>\n          <text class=\"tx-ok\" x=\"160\" y=\"214\" text-anchor=\"middle\" font-size=\"10.5\">chasse du <span class=\"kw-bio\">LCS</span> + du sang veineux</text>\n          <text class=\"tx-ok\" x=\"160\" y=\"229\" text-anchor=\"middle\" font-size=\"10.5\">PIC reste stable</text>\n          <rect class=\"fb-red\" x=\"320\" y=\"178\" width=\"220\" height=\"58\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"430\" y=\"198\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\"><span class=\"kw-alerte\">Décompensation</span></text>\n          <text class=\"tx-red\" x=\"430\" y=\"214\" text-anchor=\"middle\" font-size=\"10.5\">mécanismes dépassés</text>\n          <text class=\"tx-red\" x=\"430\" y=\"229\" text-anchor=\"middle\" font-size=\"10.5\">PIC ↑↑ (<span class=\"kw-alerte\">HTIC</span> &gt;<span class=\"kw-chiffre\"> 20 mmHg</span>)</text>\n          <rect class=\"fb-teal\" x=\"120\" y=\"244\" width=\"320\" height=\"22\" rx=\"5\"/>\n          <text class=\"tx-teal\" x=\"280\" y=\"259\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">PPC = PAM − PIC  (à maintenir &gt;<span class=\"kw-chiffre\"> 70 mmHg</span>)</text>\n          <text class=\"tx-title\" x=\"280\" y=\"286\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Courbe pression-volume de Langfitt</text>\n          <line class=\"ln\" x1=\"70\" y1=\"372\" x2=\"490\" y2=\"372\" stroke-width=\"1.5\"/>\n          <line class=\"ln\" x1=\"70\" y1=\"372\" x2=\"70\" y2=\"298\" stroke-width=\"1.5\"/>\n          <text class=\"tx-muted\" x=\"46\" y=\"336\" text-anchor=\"middle\" font-size=\"9.5\" transform=\"rotate(-90 46 336)\">PIC</text>\n          <text class=\"tx-muted\" x=\"290\" y=\"388\" text-anchor=\"middle\" font-size=\"9.5\">Volume intracrânien ajouté</text>\n          <path class=\"fb-grey\" fill=\"none\" d=\"M 78 362 C 210 360, 300 352, 350 334 C 390 318, 415 300, 432 304\" style=\"stroke-width:2.5\"/>\n          <line class=\"ln\" x1=\"70\" y1=\"330\" x2=\"490\" y2=\"330\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/>\n          <text class=\"tx-red\" x=\"494\" y=\"333\" text-anchor=\"start\" font-size=\"9.5\" font-weight=\"600\"><span class=\"kw-chiffre\">20 mmHg</span></text>\n          <text class=\"tx-ok\" x=\"190\" y=\"350\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">plateau</text>\n          <text class=\"tx-red\" x=\"412\" y=\"316\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">seuil dépassé</text>\n        </svg>\n      </figure>\n      <p><strong>Mécanismes de l'<span class=\"kw-alerte\">HTIC</span> <span class=\"kw-etio\">tumorale</span> :</strong> effet de <span class=\"kw-clinique\">masse</span> direct ; <span class=\"kw-imagerie\">œdème vasogénique</span> péri-<span class=\"kw-etio\">tumoral</span> ; <span class=\"kw-clinique\">hydrocéphalie obstructive</span> (tumeur de fosse postérieure comprimant le V4, kyste colloïde du V3) ; hémorragie intra-tumorale.</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Céphalées</span></td><td>Signe le plus précoce et constant ; récentes, inhabituelles, croissantes ; <span class=\"kw-alerte\">matinales</span>, aggravées par décubitus, <span class=\"kw-clinique\">toux</span> et effort ; <span class=\"kw-alerte\">rebelles aux antalgiques</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Vomissements</span></td><td>En <span class=\"kw-alerte\">jet</span>, sans <span class=\"kw-clinique\">nausée</span>, matinaux, sans rapport avec les repas ; soulagent partiellement la céphalée</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles visuels</span></td><td><span class=\"kw-clinique\">Diplopie horizontale</span> (paralysie du VI, sans valeur localisatrice) ; <span class=\"kw-clinique\">œdème papillaire</span> bilatéral au <span class=\"kw-imagerie\">fond d'œil</span> ; éclipses visuelles</td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles de la vigilance</span></td><td>Ralentissement, bâillements, somnolence — jusqu'au <span class=\"kw-alerte\">coma</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>📌 Particularités de l'enfant.</strong> Tant que les sutures ne sont pas fermées : augmentation du <span class=\"kw-clinique\">périmètre crânien</span> (&gt; +2 DS), <span class=\"kw-clinique\">fontanelle bombée</span>, disjonction des sutures, dilatation des veines du scalp, <span class=\"kw-clinique\">regard en coucher de soleil</span>, ralentissement des acquisitions. Formes trompeuses : <span class=\"kw-clinique\">vomissements</span> isolés, irritabilité, fléchissement scolaire.</div>\n      <div class=\"callout callout-danger\"><strong>⚠️ Engagements cérébraux — <span class=\"kw-alerte\">urgence</span> vitale absolue.</strong> Quatre types : sous-falcoriel (gyrus cingulaire sous la faux du cerveau), central cranio-caudal (diencéphale à travers l'incisure de la tente), temporal (uncus — mydriase aréactive homolatérale par compression du III, hémiplégie controlatérale, troubles de la vigilance) et amygdalien (occipital — torticolis, opisthotonos, troubles respiratoires par compression bulbaire). Signes d'alarme : <span class=\"kw-alerte\">chute du score de Glasgow</span>, <span class=\"kw-alerte\">asymétrie pupillaire</span>, <span class=\"kw-alerte\">triade de Cushing</span> (<span class=\"kw-etio\">HTA</span> + <span class=\"kw-clinique\">bradycardie</span> + irrégularité respiratoire) → imagerie et avis neurochirurgical immédiats.</div>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 420\" role=\"img\" aria-label=\"Schéma légendé d'une coupe cérébrale montrant les quatre engagements cérébraux. 1. Engagement sous-falcoriel : le gyrus cingulaire passe sous la faux du cerveau. 2. Engagement temporal ou uncal : l'uncus du lobe temporal passe par la fente de Bichat ; signes propres : mydriase aréactive homolatérale par compression du nerf oculomoteur III, hémiplégie controlatérale et coma. 3. Engagement central ou diencéphalique cranio-caudal : le diencéphale est refoulé à travers l'incisure de la tente du cervelet, avec troubles de la vigilance. 4. Engagement amygdalien : les amygdales cérébelleuses passent par le trou occipital ; signes propres : torticolis, opisthotonos et irrégularité respiratoire par compression du bulbe, mettant en jeu le pronostic vital.\" style=\"height:auto;display:block;border-radius:8px\">\n          <ellipse class=\"fb-grey\" cx=\"280\" cy=\"200\" rx=\"210\" ry=\"150\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"56\" x2=\"280\" y2=\"230\" stroke-width=\"2\"/>\n          <text class=\"tx-muted\" x=\"288\" y=\"72\" text-anchor=\"start\" font-size=\"10\">faux du cerveau</text>\n          <line class=\"ln\" x1=\"120\" y1=\"250\" x2=\"440\" y2=\"250\" stroke-width=\"2\"/>\n          <text class=\"tx-muted\" x=\"436\" y=\"244\" text-anchor=\"end\" font-size=\"10\">tente du cervelet</text>\n          <ellipse class=\"fb-purple\" cx=\"200\" cy=\"180\" rx=\"70\" ry=\"58\"/>\n          <ellipse class=\"fb-purple\" cx=\"360\" cy=\"180\" rx=\"70\" ry=\"58\"/>\n          <rect class=\"fb-amber\" x=\"250\" y=\"232\" width=\"60\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"256\" text-anchor=\"middle\" font-size=\"9.5\">tronc</text>\n          <circle class=\"fb-red\" cx=\"244\" cy=\"76\" r=\"13\"/>\n          <text class=\"tx-red\" x=\"244\" y=\"80\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">1</text>\n          <circle class=\"fb-red\" cx=\"158\" cy=\"226\" r=\"13\"/>\n          <text class=\"tx-red\" x=\"158\" y=\"230\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">2</text>\n          <circle class=\"fb-red\" cx=\"280\" cy=\"218\" r=\"13\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"222\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">3</text>\n          <circle class=\"fb-red\" cx=\"280\" cy=\"328\" r=\"13\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"332\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">4</text>\n          <line class=\"ln\" x1=\"280\" y1=\"350\" x2=\"280\" y2=\"372\" stroke-width=\"2\"/>\n          <text class=\"tx-muted\" x=\"296\" y=\"368\" text-anchor=\"start\" font-size=\"10\">trou occipital</text>\n          <rect class=\"fb-amber\" x=\"10\" y=\"384\" width=\"128\" height=\"30\" rx=\"5\"/>\n          <text class=\"tx-amber\" x=\"74\" y=\"397\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">1 · Sous-falcoriel</text>\n          <text class=\"tx-amber\" x=\"74\" y=\"409\" text-anchor=\"middle\" font-size=\"8.5\">gyrus cingulaire</text>\n          <rect class=\"fb-red\" x=\"142\" y=\"384\" width=\"140\" height=\"30\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"212\" y=\"397\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">2 · Temporal (uncus)</text>\n          <text class=\"tx-red\" x=\"212\" y=\"409\" text-anchor=\"middle\" font-size=\"8.5\">mydriase + hémiplégie</text>\n          <rect class=\"fb-amber\" x=\"286\" y=\"384\" width=\"132\" height=\"30\" rx=\"5\"/>\n          <text class=\"tx-amber\" x=\"352\" y=\"397\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">3 · Central</text>\n          <text class=\"tx-amber\" x=\"352\" y=\"409\" text-anchor=\"middle\" font-size=\"8.5\">diencéphale · vigilance</text>\n          <rect class=\"fb-red\" x=\"422\" y=\"384\" width=\"132\" height=\"30\" rx=\"5\"/>\n          <text class=\"tx-red\" x=\"488\" y=\"397\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">4 · Amygdalien</text>\n          <text class=\"tx-red\" x=\"488\" y=\"409\" text-anchor=\"middle\" font-size=\"8.5\">torticolis · ✗ bulbe</text>\n        </svg>\n      </figure>\n      <div class=\"callout callout-danger\"><strong>⚠️ <span class=\"kw-ttt\">Ponction</span> lombaire <span class=\"kw-ci\">contre-indiquée</span>.</strong> Devant des signes d'<span class=\"kw-alerte\">HTIC</span>, la <span class=\"kw-ci\">PL est formellement contre-indiquée</span> (risque d'engagement) : elle n'est autorisée qu'après une <span class=\"kw-imagerie\">imagerie cérébrale</span> ayant éliminé un processus expansif et des signes d'engagement.</div>\n      <p><strong>Prise en charge de l'<span class=\"kw-alerte\">HTIC</span> sévère :</strong></p>\n      <ul>\n        <li>Position : tête surélevée à <span class=\"kw-chiffre\">30°</span> en rectitude (favorise le <span class=\"kw-ttt\">drainage</span> veineux).</li>\n        <li>Lutte contre les <span class=\"kw-def\">ACSOS</span> : normoxie, <span class=\"kw-chiffre\">normocapnie 35-40 mmHg</span>, normothermie, normoglycémie, normonatrémie, <span class=\"kw-chiffre\">PAM &gt; 80 mmHg</span>.</li>\n        <li><span class=\"kw-ttt\">Osmothérapie</span> : mannitol <span class=\"kw-chiffre\">20 %</span> ou sérum salé hypertonique, en discontinu.</li>\n        <li><span class=\"kw-ttt\">Corticoïdes</span> (<span class=\"kw-ttt\">dexaméthasone</span>) : efficaces sur l'<span class=\"kw-clinique\">œdème</span> <span class=\"kw-imagerie\">vasogénique</span> <span class=\"kw-etio\">tumoral</span> — <span class=\"kw-ci\">inefficaces sur l'œdème cytotoxique</span> de l'<span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span> et du traumatisme.</li>\n        <li>Sédation neuroprotectrice si <span class=\"kw-alerte\">coma</span> (Glasgow &lt; 8) avec <span class=\"kw-ttt\">intubation</span> et ventilation.</li>\n        <li><span class=\"kw-ttt\">Drainage chirurgical urgent</span> (dérivation ventriculaire externe) si hydrocéphalie obstructive ; <span class=\"kw-ttt\">exérèse</span> ou volet décompressif si effet de <span class=\"kw-clinique\">masse</span> majeur.</li>\n      </ul>\n      <p><strong>II. Épilepsie sur tumeur cérébrale</strong></p>\n      <p>La crise résulte de l'<span class=\"kw-clinique\">irritation corticale</span> par la tumeur ou l'<span class=\"kw-clinique\">œdème</span>. Elle est volontiers <span class=\"kw-clinique\">focale</span> (motrice, sensitive, langage), avec ou sans généralisation secondaire, et d'autant plus fréquente que la tumeur est d'<span class=\"kw-clinique\">évolution</span> lente (gliome de bas <span class=\"kw-def\">grade</span>, méningiome). Toute <span class=\"kw-alerte\">première crise de l'adulte</span> impose une imagerie cérébrale.</p>\n      <div class=\"callout callout-danger\"><strong>⚠️ État de mal épileptique.</strong> Crise <span class=\"kw-alerte\">&gt; 5 minutes</span> ou crises subintrantes sans récupération de conscience = <span class=\"kw-alerte\">urgence</span> → <span class=\"kw-ttt\">benzodiazépine IV</span>, <span class=\"kw-def\">surveillance</span>, <span class=\"kw-imagerie\">EEG</span>.</div>\n      <p><strong>III. Prise en charge initiale conjointe</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> en milieu <span class=\"kw-ttt\">neurochirurgical</span> ; imagerie <span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-alerte\">urgence</span>.</li>\n        <li>Anti-épileptique uniquement après une crise constituée — <span class=\"kw-ci\">pas de prophylaxie systématique</span> en l'absence de crise.</li>\n        <li><span class=\"kw-ttt\">Corticoïdes</span> si <span class=\"kw-clinique\">œdème</span> vasogénique ; <span class=\"kw-ci\">pas d'AINS</span>, pas d'<span class=\"kw-ttt\">anticoagulant</span> sans avis spécialisé.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie · 340 — <span class=\"kw-alerte\">AVC</span> · 108 — Confusion, démence du sujet âgé</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/raised-intracranial-pressure","label":"Radiopaedia : Raised intracranial pressure"},{"href":"https://radiopaedia.org/articles/cerebral-edema-1","label":"Radiopaedia : Cerebral edema 1"},{"href":"http://radiopaedia.org/articles/brain-herniation-1","label":"Radiopaedia : Brain herniation 1"},{"href":"https://radiopaedia.org/articles/idiopathic-intracranial-hypertension-1","label":"Radiopaedia : Idiopathic intracranial hypertension 1"}]},{"id":"299-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes de la prise en charge de l'HTIC et de l'épilepsie chez un patient porteur d'une tumeur intra-cérébrale","contenu":"<p>La prise en charge associe en parallèle un <strong>traitement étiologique</strong> (la tumeur) et un <strong>traitement symptomatique</strong> (<span class=\"kw-alerte\">HTIC</span>, épilepsie). Toute décision est prise en <span class=\"kw-ttt\">RCP neuro-oncologique</span>.</p>\n      <p><strong>I. Traitement étiologique</strong></p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Principes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Chirurgie</span></td><td><span class=\"kw-ttt\">Exérèse</span> maximale autorisée par la fonction (neuronavigation, chirurgie éveillée pour les zones éloquentes) ; apporte aussi le diagnostic histologique et soulage l'<span class=\"kw-alerte\">HTIC</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Radiothérapie</span></td><td>Stéréotaxique (métastase &lt; <span class=\"kw-chiffre\">3 cm</span>), focale (gliome diffus), encéphale in toto (métastases multiples), craniospinale (médulloblastome)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Chimiothérapie</span></td><td><span class=\"kw-ttt\">Témozolomide</span> dans le glioblastome (<span class=\"kw-def\">protocole Stupp</span> : <span class=\"kw-ttt\">radiothérapie</span> + témozolomide concomitant puis adjuvant) ; thérapies ciblées selon le primitif des métastases</td></tr>\n        </tbody>\n      </table>\n      <p><strong>II. Prise en charge de l'<span class=\"kw-alerte\">HTIC</span> (non aiguë)</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Corticoïdes</span> (<span class=\"kw-ttt\">dexaméthasone</span>) : réduisent l'<span class=\"kw-imagerie\">œdème vasogénique</span> péri-<span class=\"kw-etio\">tumoral</span> en moins de <span class=\"kw-chiffre\">24 h</span> ; éviter les cures prolongées (effets secondaires).</li>\n        <li>Position tête surélevée à <span class=\"kw-chiffre\">30°</span> ; restriction hydrique modérée si hyponatrémie.</li>\n        <li>Hydrocéphalie obstructive symptomatique : <span class=\"kw-ttt\">dérivation ventriculaire</span> (DVP en chronique, DVE en aigu) ou <span class=\"kw-ttt\">ventriculocisternostomie endoscopique</span> selon la topographie de l'obstacle.</li>\n        <li><span class=\"kw-def\">Surveillance</span> clinique (<span class=\"kw-clinique\">céphalées</span>, vigilance, <span class=\"kw-imagerie\">fond d'œil</span>) et par <span class=\"kw-imagerie\">IRM</span> selon le rythme défini en <span class=\"kw-def\">RCP</span>.</li>\n      </ul>\n      <p><strong>III. Prise en charge de l'épilepsie <span class=\"kw-etio\">tumorale</span></strong></p>\n      <ul>\n        <li>Anti-épileptique <strong>uniquement après une ou des crises constituées</strong> — <span class=\"kw-ci\">pas de prophylaxie systématique</span> ; un traitement péri-opératoire de <span class=\"kw-chiffre\">7 à 14 jours</span> peut se discuter.</li>\n        <li>Privilégier les molécules <strong>non inductrices enzymatiques</strong> : <span class=\"kw-ttt\">lévétiracétam</span>, <span class=\"kw-ttt\">lacosamide</span>, <span class=\"kw-ttt\">lamotrigine</span>.</li>\n        <li><span class=\"kw-ci\">Éviter phénytoïne et carbamazépine</span> (inducteurs du cytochrome P450, interactions avec la <span class=\"kw-ttt\">chimiothérapie</span>).</li>\n        <li>Conséquences sociales : <span class=\"kw-alerte\">interdiction de conduite</span>, aménagement professionnel.</li>\n      </ul>\n      <p><strong>IV. <span class=\"kw-def\">Suivi</span> au long cours</strong></p>\n      <ul>\n        <li>Consultations de neuro-oncologie pluridisciplinaires ; <span class=\"kw-imagerie\">IRM</span> de <span class=\"kw-def\">surveillance</span> (<span class=\"kw-chiffre\">3-6-12 mois</span>).</li>\n        <li>Bilan neuropsychologique (séquelles cognitives de la <span class=\"kw-ttt\">radiothérapie</span> et de la chimiothérapie).</li>\n        <li>Réinsertion : <span class=\"kw-def\">ALD</span>, soutien psychologique, soins palliatifs si <span class=\"kw-def\">pronostic</span> réservé ; prise en charge des aidants.</li>\n      </ul>\n      <p><strong>V. <span class=\"kw-def\">Pronostic</span></strong> — très variable selon le type :</p>\n      <table >\n        <thead><tr><th>Tumeur</th><th>Pronostic</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Méningiome grade 1</span></td><td>Excellent après <span class=\"kw-ttt\">exérèse</span> complète</td></tr>\n          <tr><td><span class=\"kw-etio\">Schwannome</span></td><td>Excellent après <span class=\"kw-ttt\">exérèse</span> ou radiochirurgie</td></tr>\n          <tr><td><span class=\"kw-etio\">Glioblastome</span></td><td><span class=\"kw-alerte\">Sombre</span> — médiane de survie <span class=\"kw-chiffre\">12-18 mois</span> malgré le <span class=\"kw-def\">protocole Stupp</span> ; récidive locale quasi constante</td></tr>\n          <tr><td><span class=\"kw-etio\">Métastase cérébrale</span></td><td>Réservé — dépend du primitif, du nombre de lésions et de l'état fonctionnel (<span class=\"kw-def\">score de Karnofsky</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>⚠️ Patient porteur d'une dérivation.</strong> Devant une <span class=\"kw-clinique\">fièvre</span> avec <span class=\"kw-alerte\">syndrome méningé</span> chez un patient porteur d'une <span class=\"kw-ttt\">DVP</span>, évoquer une <span class=\"kw-alerte\">infection du matériel de dérivation</span> (<span class=\"kw-alerte\">méningite</span>, ventriculite) imposant souvent l'ablation du matériel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie · 151 — Méningite - méningoencéphalite · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/normal-pressure-hydrocephalus","label":"Radiopaedia : Normal pressure hydrocephalus"}]}],"astuces":[{"type":"danger","titre":"Toute première crise d'épilepsie de l'adulte = IRM cérébrale","contenu":"Une première crise convulsive chez un adulte impose une IRM cérébrale en urgence relative pour éliminer une tumeur, un AVC, une malformation vasculaire ou une lésion inflammatoire. Ne JAMAIS se contenter d'un simple EEG."},{"type":"warn","titre":"Céphalées matinales + vomissements en jet = HTIC tumorale","contenu":"Triade typique : céphalées matinales (réveillent le patient), aggravées par le décubitus/la toux/le Valsalva, résistantes aux antalgiques + vomissements en jet sans nausée préalable soulageant transitoirement + œdème papillaire bilatéral au FO. IRM cérébrale en urgence."},{"type":"tip","titre":"Lévétiracétam (Keppra) en 1ère intention chez le patient tumoral","contenu":"Le Keppra est l'antiépileptique de choix car il n'a quasiment pas d'interactions médicamenteuses (compatible avec chimio, corticoïdes, anticoagulants). À éviter : phénytoïne, carbamazépine, phénobarbital (inducteurs enzymatiques → effondrent les concentrations de chimiothérapie)."},{"type":"danger","titre":"Mydriase aréactive = engagement temporal = urgence vitale","contenu":"Mydriase aréactive unilatérale + hémiparésie controlatérale + altération de la conscience = engagement uncal du lobe temporal sur le bord libre de la tente du cervelet. Compression du III homolatéral. Corticothérapie IV + mannitol + neurochirurgie en extrême urgence."},{"type":"info","titre":"Métastase cérébrale → toujours rechercher le primitif (poumon 50 %)","contenu":"Devant une métastase cérébrale (lésions multiples, prise de contraste en cocarde, jonction substance grise/blanche), bilan systématique : TDM TAP injecté, mammographie, examen cutané, marqueurs tumoraux, PET-scan si négatif. Primitif retrouvé : poumon (50 %), sein (20 %), mélanome (10 %)."},{"type":"warn","titre":"Lymphome cérébral : PAS de corticoïdes avant la biopsie","contenu":"Si suspicion de lymphome primitif du SNC (sujet âgé/immunodéprimé, prise de contraste homogène, péri-ventriculaire), NE PAS donner de corticoïdes avant la biopsie : ils font fondre les cellules lymphomateuses et rendent la biopsie ininterprétable (lymphome corticosensible)."}],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">HTIC</span> aiguë &amp; engagement cérébral <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale absolue</span></strong></p><p><span class=\"kw-imagerie\">imagerie cérébrale</span> (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>) + avis <span class=\"kw-ttt\">neurochirurgical</span> immédiats ; <span class=\"kw-ci\">PL contre-indiquée</span></p><ul><li>PIC <span class=\"kw-chiffre\">&gt; 20 mmHg</span> = <span class=\"kw-def\">HTIC</span> pathologique ; courbe de <span class=\"kw-def\">Langfitt</span> exponentielle → <span class=\"kw-alerte\">décompensation</span> <span class=\"kw-alerte\">imprévisible</span></li><li>Alerte : <span class=\"kw-alerte\">chute du score de Glasgow</span>, <span class=\"kw-alerte\">asymétrie pupillaire</span> (mydriase aréactive), <span class=\"kw-alerte\">triade de Cushing</span> (<span class=\"kw-etio\">HTA</span> + <span class=\"kw-clinique\">bradycardie</span> + irrégularité respiratoire)</li></ul><p><strong>Hydrocéphalie aiguë obstructive</strong></p><p><span class=\"kw-ttt\">dérivation ventriculaire externe (DVE)</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li>Dilatation ventriculaire en amont d’un <span class=\"kw-etio\">obstacle</span> (tumeur de fosse postérieure comprimant le <span class=\"kw-clinique\">V4</span>, kyste colloïde du <span class=\"kw-clinique\">V3</span>)</li><li><span class=\"kw-alerte\">Décompensation</span> d’autant plus rapide que l’obstacle est <span class=\"kw-chiffre\">rostral</span></li></ul><p><strong>État de mal épileptique</strong></p><p><span class=\"kw-ttt\">benzodiazépine IV</span>, <span class=\"kw-def\">surveillance</span>, <span class=\"kw-bio\">EEG</span></p><ul><li>Crise <span class=\"kw-alerte\">&gt; 5 min</span> ou crises subintrantes sans reprise de conscience</li></ul><p><strong>Première crise d’épilepsie de l’adulte <span class=\"q\">— dogme</span></strong></p><p><span class=\"kw-imagerie\">imagerie cérébrale</span> systématique à la recherche d’une tumeur</p>","hospit":"<p><strong>Hospit systématique :</strong> milieu <span class=\"kw-ttt\">neurochirurgical</span> ; <span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-alerte\">urgence</span>.<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> formes aiguës (<span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-alerte\">engagement</span>, <span class=\"kw-alerte\">coma</span> Glasgow <span class=\"kw-chiffre\">&lt; 8</span>) en réa proche d’un service de neurochirurgie.<br><strong>Décision thérapeutique :</strong> toute décision prise en <span class=\"kw-ttt\">RCP neuro-oncologique</span>.<br><strong><span class=\"kw-def\">Surveillance</span> simple :</strong> licite devant une <span class=\"kw-clinique\">lésion</span> bénigne asymptomatique (<span class=\"kw-etio\">méningiome</span> de découverte fortuite).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Chute du score de Glasgow</span> / troubles de la vigilance jusqu’au <span class=\"kw-alerte\">coma</span></li><li><span class=\"kw-alerte\">Mydriase aréactive homolatérale</span> + <span class=\"kw-clinique\">hémiplégie</span> controlatérale → engagement <span class=\"kw-def\">temporal</span> (compression du III)</li><li><span class=\"kw-alerte\">Triade de Cushing</span> : <span class=\"kw-clinique\">HTA</span> + <span class=\"kw-clinique\">bradycardie</span> + <span class=\"kw-clinique\">irrégularité respiratoire</span></li><li><span class=\"kw-alerte\">Torticolis</span>, <span class=\"kw-alerte\">opisthotonos</span>, irrégularité respiratoire → engagement <span class=\"kw-def\">amygdalien</span> (compression bulbaire)</li><li><span class=\"kw-clinique\">Céphalées</span> matinales rebelles aux <span class=\"kw-ttt\">antalgiques</span> + <span class=\"kw-clinique\">vomissements en jet</span> + <span class=\"kw-clinique\">œdème papillaire</span> bilatéral (<span class=\"kw-alerte\">HTIC</span>)</li><li>Crise épileptique <span class=\"kw-alerte\">&gt; 5 min</span> ou crises subintrantes (<span class=\"kw-alerte\">état de mal</span>)</li><li><span class=\"kw-imagerie\">TDM</span> : <span class=\"kw-imagerie\">effacement des sillons et des citernes de la base</span>, dédifférenciation substance grise / blanche, <span class=\"kw-alerte\">engagement</span></li><li>Enfant : augmentation du <span class=\"kw-clinique\">périmètre crânien</span>, <span class=\"kw-clinique\">fontanelle bombée</span>, <span class=\"kw-clinique\">regard en coucher de soleil</span></li></ul>","principes":"<p><strong>Règle d’or :</strong> traitement <span class=\"kw-def\">étiologique</span> (la tumeur) et <span class=\"kw-def\">symptomatique</span> (<span class=\"kw-alerte\">HTIC</span>, épilepsie) menés <strong>en parallèle</strong> ; <span class=\"kw-ci\">aucun anti-épileptique prophylactique</span> sans crise constituée.</p><p><strong><span class=\"kw-alerte\">HTIC</span> sévère — mesures générales</strong></p><ul><li>Tête surélevée à <span class=\"kw-chiffre\">30°</span> en rectitude (<span class=\"kw-ttt\">drainage</span> veineux)</li><li>Lutte contre les <span class=\"kw-def\">ACSOS</span> : normoxie, <span class=\"kw-chiffre\">normocapnie 35-40 mmHg</span>, normothermie, normoglycémie, normonatrémie, <span class=\"kw-chiffre\">PAM &gt; 80 mmHg</span>, <span class=\"kw-chiffre\">PPC &gt; 70 mmHg</span></li><li><span class=\"kw-ttt\">Osmothérapie</span> : mannitol <span class=\"kw-chiffre\">20 %</span> ou sérum salé hypertonique, en discontinu (effet rapide transitoire, risque de rebond)</li><li><span class=\"kw-ttt\">Corticoïdes</span> (<span class=\"kw-ttt\">dexaméthasone</span>) : efficaces sur l’<span class=\"kw-imagerie\">œdème vasogénique</span> <span class=\"kw-etio\">tumoral</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>) — <span class=\"kw-ci\">inefficaces sur l’œdème cytotoxique</span> (<span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span>, traumatisme)</li><li><span class=\"kw-ttt\">Sédation neuroprotectrice</span> + <span class=\"kw-ttt\">intubation</span> si <span class=\"kw-alerte\">coma</span> (Glasgow <span class=\"kw-chiffre\">&lt; 8</span>) ; <span class=\"kw-ttt\">barbituriques</span> si <span class=\"kw-alerte\">HTIC</span> réfractaire</li></ul><p><strong>Hydrocéphalie — traitement neurochirurgical</strong></p><ul><li><span class=\"kw-ttt\">Dérivation ventriculaire externe (DVE)</span> : <span class=\"kw-ttt\">drainage</span> provisoire en <span class=\"kw-alerte\">urgence</span> (aiguë), <span class=\"kw-alerte\">risque infectieux</span> (≤ <span class=\"kw-chiffre\">15 jours</span>)</li><li><span class=\"kw-ttt\">Dérivation interne (DVP ++, DVA)</span> : traitement définitif de l’hydrocéphalie chronique</li><li><span class=\"kw-ttt\">Ventriculocisternostomie endoscopique</span> : hydrocéphalie obstructive (obstacle aqueduc / V4), sans matériel étranger</li><li><span class=\"kw-ttt\">Exérèse tumorale</span> / <span class=\"kw-ttt\">craniectomie décompressive</span> si effet de <span class=\"kw-clinique\">masse</span> majeur</li></ul><p><strong>Épilepsie <span class=\"kw-etio\">tumorale</span></strong></p><ul><li>Anti-épileptique <strong>uniquement après crise constituée</strong> — <span class=\"kw-ci\">pas de prophylaxie systématique</span> (péri-opératoire <span class=\"kw-chiffre\">7-14 jours</span> possible)</li><li>Molécules <strong>non inductrices enzymatiques</strong> : <span class=\"kw-ttt\">lévétiracétam</span>, <span class=\"kw-ttt\">lacosamide</span>, <span class=\"kw-ttt\">lamotrigine</span></li><li><span class=\"kw-ci\">Éviter phénytoïne et carbamazépine</span> (inducteurs du P450, interactions avec la <span class=\"kw-ttt\">chimiothérapie</span>)</li></ul><p><strong>Traitement étiologique de la tumeur</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">exérèse</span> maximale autorisée par la fonction + diagnostic histologique</li><li><span class=\"kw-ttt\">Radiothérapie</span> : stéréotaxique (métastase <span class=\"kw-chiffre\">&lt; 3 cm</span>), focale (gliome diffus), encéphale in toto (métastases multiples), craniospinale (médulloblastome)</li><li><span class=\"kw-ttt\">Chimiothérapie</span> : <span class=\"kw-ttt\">témozolomide</span> dans le glioblastome (<span class=\"kw-def\">protocole Stupp</span>)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> clinique &amp; imagerie</strong></p><ul><li><span class=\"kw-alerte\">HTIC</span> : <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">vigilance</span>, <span class=\"kw-bio\">fond d’œil</span></li><li><span class=\"kw-imagerie\">IRM</span> de <span class=\"kw-def\">surveillance</span> : <span class=\"kw-chiffre\">3-6-12 mois</span> selon le rythme défini en <span class=\"kw-def\">RCP</span></li><li><span class=\"kw-bio\">Bilan neuropsychologique</span> : séquelles cognitives de la <span class=\"kw-ttt\">radiothérapie</span> / chimiothérapie</li></ul><p><strong>Patient porteur d’une dérivation (DVP / DVA)</strong></p><p><span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">syndrome méningé</span> → évoquer une <span class=\"kw-alerte\">infection du matériel</span> (<span class=\"kw-alerte\">méningite</span>, ventriculite) imposant l’ablation</p><ul><li><span class=\"kw-def\">Surveillance</span> au long cours : complications mécaniques (obstruction de valve, migration ou fracture de cathéter)</li><li><span class=\"kw-alerte\">Hématome sous-dural</span></li></ul><p><strong>Épilepsie &amp; vie quotidienne</strong></p><ul><li><span class=\"kw-alerte\">Interdiction de conduite</span>, aménagement professionnel</li></ul><p><strong>Réinsertion &amp; soins de support</strong></p><ul><li><span class=\"kw-ttt\">ALD</span>, soutien psychologique, prise en charge des aidants</li><li><span class=\"kw-ttt\">Soins palliatifs</span> si <span class=\"kw-def\">pronostic</span> réservé</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/troubles-de-la-marche-et-de-lequilibre-troubles-de-la-marche-et-de-lequilibre-chez-le-sujet-age","label":"Collège (CEN) — Troubles de la marche et de lequilibre troubles de la marche et de lequilibre chez le sujet age"},{"href":"https://campus.neurochirurgie.fr/article1716.html","label":"Collège — Article1716"},{"href":"https://campus.neurochirurgie.fr/article1532.html","label":"Collège — Article1532"},{"href":"https://campus.neurochirurgie.fr/article1781.html","label":"Collège — Article1781"},{"href":"https://info-radiologie.ch/engagement-temporal","label":"Engagement temporal"},{"href":"https://www.ce-mir.fr/files/medias/documents/28.%20Le%20scanner%20c%C3%A9r%C3%A9bral%20en%20soins%20critiques.pdf","label":"CeMIR — 28. le scanner cérébral en soins critiques"},{"href":"https://fr.wikipedia.org/wiki/%C5%92d%C3%A8me_papillaire","label":"Fond d’oeil"},{"href":"https://www.cen-neurologie.fr/second-cycle/tumeurs-intracraniennes","label":"Collège (CEN) — Tumeurs intracraniennes"},{"href":"https://campus.neurochirurgie.fr/article1782.html","label":"Collège — Article1782"},{"href":"https://campus.neurochirurgie.fr/article1783.html","label":"Collège — Article1783"},{"href":"https://radiopaedia.org/articles/brain-tumors-1","label":"Radiopaedia : Brain tumors 1"},{"href":"https://radiopaedia.org/articles/ventricular-system","label":"Radiopaedia : Ventricular system"},{"href":"https://radiopaedia.org/articles/cerebral-venous-system","label":"Radiopaedia : Cerebral venous system"},{"href":"https://www.imaios.com/fr/e-anatomy/cerveau/angioirm-veineuse-cerebrale","label":"IMAIOS e-Anatomy — Angioirm veineuse cerebrale"}],"cards":[{"i":"4a25e438c997","n":299,"o":"299-1","u":"Définition","t":"Connaître les principaux types et localisations des tumeurs intracrâniennes","q":"Quelle est la localisation préférentielle des tumeurs intracrâniennes chez l'adulte et chez l'enfant ?","a":"<ul><li>Chez l'<strong>adulte</strong> : les tumeurs sont volontiers <strong>sus-tentorielles</strong> (80 % des cas). La <strong>métastase</strong> est la plus fréquente.</li><li>Chez l'<strong>enfant</strong> : la <strong>fosse postérieure</strong> est touchée dans environ 50 % des cas.</li></ul>"},{"i":"8db5bd8fd912","n":299,"o":"299-1","u":"Définition","t":"Connaître les principaux types et localisations des tumeurs intracrâniennes","q":"Qu'est-ce qu'une tumeur intracrânienne et quels sont ses principaux types ?","a":"<p>Une tumeur intracrânienne est toute <strong>prolifération cellulaire</strong> développée à l'intérieur de la boîte crânienne.</p><p>On distingue deux types principaux :</p><ul><li>Les <strong>tumeurs primitives</strong> : nées du système nerveux central ou de ses annexes.</li><li>Les <strong>tumeurs secondaires</strong> (ou métastases) : provenant d'un cancer extra-cérébral.</li></ul>"},{"i":"ce6e2f27c867","n":299,"o":"299-1","u":"Définition","t":"Connaître les principaux types et localisations des tumeurs intracrâniennes","q":"Quels sont les principaux types de tumeurs intracrâniennes et leurs caractéristiques chez l'adulte et l'enfant ?","a":"<ul><li><strong>Chez l'adulte</strong> : les plus fréquentes sont les <strong>métastases</strong> (souvent multiples, sus-tentorielles), puis le <strong>glioblastome</strong> (maligne, hémisphères sus-tentoriels), le <strong>méningiome</strong> (bénin, extra-axial), l'<strong>adénome hypophysaire</strong> (bénin, région sellaire), et le <strong>lymphome primitif du SNC</strong> (maligne, périventriculaire).</li><li><strong>Chez l'enfant</strong> : on retrouve principalement le <strong>médulloblastome</strong> (maligne, fosse postérieure), l'<strong>astrocytome pilocytique</strong> (bénin, cervelet ou ligne médiane) et le <strong>craniopharyngiome</strong> (bénin, sellaire/suprasellaire).</li></ul>"},{"i":"0e1807e959ac","n":299,"o":"299-2","u":"Définition","t":"Connaître la définition des tumeurs primitives intracrâniennes : système nerveux central et annexes","q":"Quelle est la définition d'une tumeur primitive intracrânienne ?","a":"<p>Une tumeur primitive intracrânienne est une <strong>prolifération cellulaire</strong> née à l'intérieur du crâne, se développant à partir des tissus du <strong>système nerveux central (SNC)</strong> ou de ses <strong>annexes</strong>.</p>"},{"i":"0f53eff4bff0","n":299,"o":"299-2","u":"Définition","t":"Connaître la définition des tumeurs primitives intracrâniennes : système nerveux central et annexes","q":"Pourquoi la distinction entre tumeur bénigne et maligne n'est-elle pas suffisante pour préjuger de la morbidité des tumeurs intracrâniennes ?","a":"<p>Une tumeur histologiquement <strong>bénigne</strong> peut rester menaçante et entraîner une morbidité significative par son <strong>effet de masse</strong> (causant une hypertension intracrânienne ou un engagement cérébral) ou par sa <strong>localisation</strong> rendant une exérèse chirurgicale difficile voire impossible. Des exemples de tumeurs habituellement bénignes sont les <strong>méningiomes typiques</strong>, les <strong>schwannomes</strong>, les <strong>adénomes hypophysaires</strong> et l'<strong>astrocytome pilocytique</strong>.</p>"},{"i":"2ce3a1e186ae","n":299,"o":"299-2","u":"Définition","t":"Connaître la définition des tumeurs primitives intracrâniennes : système nerveux central et annexes","q":"Donnez des exemples de tumeurs primitives intracrâniennes selon leur tissu d'origine, qu'elles soient du SNC ou de ses annexes.","a":"<ul><li><strong>SNC (exemples)</strong> :<ul><li>Astrocytes : <strong>astrocytomes</strong> (dont glioblastome)</li><li>Oligodendrocytes : <strong>oligodendrogliomes</strong></li><li>Épendymocytes / cellules embryonnaires : <strong>épendymomes</strong>, <strong>médulloblastomes</strong></li></ul></li><li><strong>Annexes du SNC (exemples)</strong> :<ul><li>Méninges : <strong>méningiomes</strong></li><li>Gaines nerveuses : <strong>neurinomes</strong> (schwannomes)</li><li>Axe hypothalamo-hypophysaire : <strong>adénomes hypophysaires</strong>, <strong>craniopharyngiomes</strong></li></ul></li></ul>"},{"i":"326e0b7edc84","n":299,"o":"299-2","u":"Définition","t":"Connaître la définition des tumeurs primitives intracrâniennes : système nerveux central et annexes","q":"Comment les tumeurs primitives du SNC sont-elles classifiées et pourquoi le système TNM n'est-il pas applicable ?","a":"<p>Les tumeurs primitives du SNC ne sont pas classifiées selon le système <strong>TNM</strong>. La classification <strong>OMS 2021</strong> les gradue de <strong>1 à 4</strong> selon leur agressivité, en croisant les critères <strong>histologiques</strong> (cellule d'origine) et les <strong>marqueurs biomoléculaires</strong>. Le TNM n'est pas applicable en l'absence de système lymphatique et d'une dissémination métastatique hors SNC beaucoup plus rare.</p>"},{"i":"1be74056e9bb","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Comment se manifeste un déficit neurologique focal lié à une tumeur intracrânienne et quel est son mécanisme ?","a":"<p>Le déficit neurologique focal se manifeste par :</p><ul><li>Un déficit moteur ou sensitif.</li><li>Une aphasie.</li><li>Une hémianopsie.</li><li>Une ataxie cérébelleuse.</li><li>Une atteinte de nerfs crâniens.</li></ul><p>Son installation est classiquement <strong>progressive, « en tache d'huile »</strong>. Le mécanisme est la <strong>compression ou l'infiltration du parenchyme</strong>, aggravée par un œdème.</p>"},{"i":"347b5af1e472","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Quel est le mécanisme d'une crise d'épilepsie révélatrice d'une tumeur intracrânienne et quels types de tumeurs sont particulièrement concernées ?","a":"<p>Le mécanisme de la crise d'épilepsie est l'<strong>irritation du cortex cérébral</strong> par la tumeur. Elle révèle <strong>20 à 40 %</strong> des tumeurs.</p><p>Les tumeurs particulièrement concernées sont celles qui sont au <strong>contact du cortex</strong>, comme les <strong>gliomes de bas grade</strong> et les <strong>méningiomes</strong>.</p>"},{"i":"3ea5bfdf676f","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Quelles sont les particularités des signes cliniques de tumeur intracrânienne chez l'enfant ?","a":"<p>Chez l'enfant, les particularités sont :</p><ul><li>Une <strong>augmentation du périmètre crânien</strong>.</li><li>Une <strong>fontanelle bombée</strong>.</li><li>Un <strong>regard en coucher de soleil</strong>.</li><li>Un <strong>torticolis persistant</strong>.</li><li>Des <strong>vomissements matinaux pseudo-digestifs</strong>.</li><li>Un <strong>fléchissement scolaire</strong>.</li></ul><p>Les présentations sont souvent <strong>frustes et trompeuses</strong>.</p>"},{"i":"5811efcfff59","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Face à une première crise d'épilepsie chez l'adulte, quel est le dogme essentiel à retenir concernant l'exploration diagnostique ?","a":"<p>Le dogme est que toute <strong>première crise d'épilepsie chez un adulte</strong> impose la réalisation d'une <strong>imagerie cérébrale</strong> afin de rechercher une tumeur intracrânienne.</p>"},{"i":"5afbb4fd2c16","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Quels sont les quatre grands tableaux cliniques révélant une tumeur intracrânienne, non spécifiques mais devant alerter par leur installation progressive ou leur association ?","a":"<p>Les quatre grands tableaux cliniques sont :</p><ul><li>Le <strong>syndrome d'hypertension intracrânienne (HTIC)</strong>,</li><li>La <strong>crise d'épilepsie</strong>,</li><li>Le <strong>déficit neurologique focal</strong>,</li><li>Les <strong>troubles cognitifs et comportementaux</strong>.</li></ul>"},{"i":"6668f7a561d7","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Quels types de troubles cognitifs et comportementaux peuvent révéler une tumeur intracrânienne, et quelles étiologies sont à considérer, notamment chez le sujet âgé ?","a":"<p>Les troubles cognitifs et comportementaux peuvent inclure un <strong>syndrome frontal</strong>, des <strong>troubles mnésiques</strong>, un <strong>ralentissement</strong>, une <strong>modification du caractère</strong>, ou un <strong>syndrome confusionnel ou démentiel progressif</strong>.</p><p>Ces tableaux suggèrent des lésions multiples ou étendues, telles que les <strong>métastases</strong>, le <strong>gliome infiltrant</strong> ou le <strong>lymphome</strong>, particulièrement chez le sujet âgé.</p>"},{"i":"f528cb3e266e","n":299,"o":"299-5","u":"Diagnostic positif","t":"Connaître les principaux tableaux cliniques devant faire évoquer une tumeur intracrânienne","q":"Quels sont les signes cliniques du syndrome d'hypertension intracrânienne (HTIC) et leurs mécanismes généraux, en rapport avec une tumeur intracrânienne ?","a":"<p>Les signes cliniques du syndrome d'HTIC sont :</p><ul><li>Des <strong>céphalées matinales</strong>, croissantes, rebelles aux antalgiques.</li><li>Des <strong>vomissements en jet</strong>.</li><li>Un <strong>œdème papillaire au fond d'œil</strong>.</li><li>Une <strong>diplopie</strong> (paralysie du VI).</li></ul><p>Ces signes résultent d'un <strong>effet de masse</strong> de la tumeur, d'un <strong>œdème péri-tumoral</strong> ou d'une <strong>hydrocéphalie</strong>.</p>"},{"i":"1545703933bc","n":299,"o":"299-7","u":"Diagnostic positif","t":"Décrire la recherche systématique de cancer primitif à effectuer devant une métastase cérébrale","q":"Quels sont les cancers primitifs les plus fréquemment retrouvés à l'origine des métastases cérébrales ?","a":"<ul><li><strong>Poumon</strong> (cancer bronchique) : le plus fréquent.</li><li><strong>Peau</strong> : mélanome (fort tropisme cérébral, métastases volontiers hémorragiques).</li><li><strong>Sein</strong> : chez la femme.</li><li><strong>Rein</strong> : carcinome à cellules claires (métastases hémorragiques).</li><li><strong>Côlon</strong> et cancers digestifs : plus rarement.</li></ul>"},{"i":"5e3fc50b47bf","n":299,"o":"299-7","u":"Diagnostic positif","t":"Décrire la recherche systématique de cancer primitif à effectuer devant une métastase cérébrale","q":"Dans quel contexte l'IRM seule peut-elle suffire pour le diagnostic de métastase cérébrale, sans nécessiter d'histologie ?","a":"<p>L'IRM seule peut suffire si le <strong>cancer primitif est déjà connu et évolutif</strong>. Dans ce cas, le diagnostic de métastase peut être retenu sur les caractéristiques IRM. Si le primitif est inconnu, l'histologie est nécessaire.</p>"},{"i":"b699c73eda52","n":299,"o":"299-7","u":"Diagnostic positif","t":"Décrire la recherche systématique de cancer primitif à effectuer devant une métastase cérébrale","q":"Quels sont les cancers primitifs dont les métastases cérébrales peuvent se révéler par un accident vasculaire cérébral (AVC) hémorragique ?","a":"<p>Les métastases cérébrales de <strong>mélanome</strong> et de <strong>carcinome à cellules claires du rein</strong> sont connues pour pouvoir se révéler par un AVC hémorragique.</p>"},{"i":"ede0b334d1b6","n":299,"o":"299-7","u":"Diagnostic positif","t":"Décrire la recherche systématique de cancer primitif à effectuer devant une métastase cérébrale","q":"Quels sont les examens complémentaires clés à réaliser systématiquement lors du bilan étiologique d'une métastase cérébrale pour rechercher le primitif ?","a":"<ul><li><strong>Imagerie d'extension</strong> : TDM thoraco-abdomino-pelvienne injectée ± TEP-TDM au 18F-FDG (pour rechercher le primitif et d'autres localisations).</li><li><strong>Examens orientés</strong> selon le contexte : mammographie ± échographie chez la femme, fibroscopie bronchique chez le patient tabagique, examen dermatologique entier en cas de suspicion de mélanome.</li><li><strong>Biologie</strong> : NFS, bilan hépatique, créatininémie, calcémie, LDH, et marqueurs tumoraux orientés.</li><li><strong>Histologie</strong> : par biopsie périphérique si un primitif est identifié et accessible, ou par biopsie stéréotaxique cérébrale avec immunohistochimie d'orientation si le primitif est inconnu.</li></ul>"},{"i":"fa70cb79a159","n":299,"o":"299-7","u":"Diagnostic positif","t":"Décrire la recherche systématique de cancer primitif à effectuer devant une métastase cérébrale","q":"Quelle est la première cause de tumeur intracrânienne de l'adulte et dans quelle proportion une métastase cérébrale est-elle révélatrice du cancer primaire ?","a":"<p>La première cause de tumeur intracrânienne de l'adulte est la <strong>métastase cérébrale</strong>. Elle est révélatrice du cancer primaire dans environ <strong>20%</strong> des cas.</p>"},{"i":"4d212b06425b","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Quand suspecter une crise d'épilepsie liée à une tumeur cérébrale chez l'adulte et quelle conduite tenir ?","a":"<p>Une crise d'épilepsie est fréquente en cas de tumeur cérébrale, résultant de l'<strong>irritation corticale</strong>. Elle est souvent <strong>focale</strong> (motrice, sensitive, langage) avec ou sans généralisation secondaire. Toute <strong>première crise de l'adulte</strong> impose la réalisation d'une <strong>imagerie cérébrale</strong> en urgence (IRM en milieu neurochirurgical). L'anti-épileptique n'est administré qu'après une crise constituée, sans prophylaxie systématique.</p>"},{"i":"96342775ecf2","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Comment définir une hypertension intracrânienne (HTIC) et sa gravité chez un patient porteur d'une tumeur cérébrale ?","a":"<p>L'HTIC se définit par une Pression Intracrânienne (PIC) supérieure à <strong>15 mmHg</strong> (la normale étant 5-15 mmHg). Au-delà de <strong>20 mmHg</strong>, elle est considérée comme franchement pathologique.</p>"},{"i":"a676e4ae4259","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Pourquoi la ponction lombaire est-elle contre-indiquée en présence de signes d'HTIC chez un patient porteur d'une tumeur cérébrale ?","a":"<p>La ponction lombaire est formellement <strong>contre-indiquée</strong> en présence de signes d'HTIC (surtout s'il existe une masse) en raison du <strong>risque d'engagement cérébral</strong>. Elle n'est autorisée qu'après une imagerie cérébrale ayant éliminé un processus expansif et des signes d'engagement.</p>"},{"i":"b61a713d5213","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Quelles sont les particularités des signes d'HTIC chez l'enfant avant la fermeture des sutures crâniennes ?","a":"<ul><li><strong>Augmentation du périmètre crânien</strong> (&gt; +2 DS).</li><li><strong>Fontanelle bombée</strong>.</li><li><strong>Disjonction des sutures</strong>.</li><li>Dilatation des veines du scalp.</li><li><strong>Regard en coucher de soleil</strong>.</li><li>Ralentissement des acquisitions.</li></ul>"},{"i":"c57c516a9caf","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Quels sont les signes d'alarme devant faire craindre un engagement cérébral chez un patient présentant des signes d'HTIC ?","a":"<p>Il s'agit d'une urgence vitale absolue. Les signes d'alarme sont :</p><ul><li>Chute du <strong>score de Glasgow</strong>.</li><li><strong>Asymétrie pupillaire</strong>.</li><li><strong>Triade de Cushing</strong> (hypertension artérielle + bradycardie + irrégularité respiratoire).</li></ul><p>Ces signes imposent une imagerie et un avis neurochirurgical immédiats.</p>"},{"i":"e35c3a621afd","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Quels sont les signes cliniques classiques permettant d'évoquer une hypertension intracrânienne (HTIC) chez un patient porteur d'une tumeur ?","a":"<ul><li><strong>Céphalées</strong> : les plus précoces et constantes, récentes, inhabituelles, croissantes, <strong>matinales</strong>, aggravées par le décubitus, la toux et l'effort, rebelles aux antalgiques.</li><li><strong>Vomissements</strong> : <strong>en jet</strong>, sans nausée, matinaux, sans rapport avec les repas, soulageant partiellement la céphalée.</li><li><strong>Troubles visuels</strong> : <strong>diplopie horizontale</strong> (paralysie du VI sans valeur localisatrice), <strong>œdème papillaire bilatéral</strong> au fond d'œil, éclipses visuelles.</li><li><strong>Troubles de la vigilance</strong> : ralentissement, bâillements, somnolence, pouvant aller jusqu'au coma.</li></ul>"},{"i":"e51f828d83f2","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Quel est le traitement initial urgent d'une HTIC sévère chez un patient porteur d'une tumeur cérébrale ?","a":"<ul><li><strong>Position</strong> : tête surélevée à <strong>30°</strong> en rectitude pour favoriser le drainage veineux.</li><li>Lutte contre les <strong>ACSOS</strong> : normoxie, normocapnie (<strong>35-40 mmHg</strong>), normothermie, normoglycémie, normonatrémie, Pression Artérielle Moyenne (PAM) <strong>&gt; 80 mmHg</strong>.</li><li><strong>Osmothérapie</strong> : <strong>mannitol 20 %</strong> ou sérum salé hypertonique, en discontinu.</li><li><strong>Corticoïdes</strong> (<strong>dexaméthasone</strong>) : efficaces sur l'œdème vasogénique tumoral.</li><li><strong>Sédation neuroprotectrice</strong> si coma (Glasgow &lt; 8) avec intubation et ventilation.</li><li><strong>Drainage chirurgical urgent</strong> (dérivation ventriculaire externe) si hydrocéphalie obstructive ; exérèse tumorale ou volet décompressif si effet de masse majeur.</li></ul>"},{"i":"fe1b9eb1c638","n":299,"o":"299-8","u":"Identifier une urgence","t":"Savoir évoquer une hypertension intracrânienne (HTIC) et une épilepsie chez un patient porteur d'une tumeur intra-cérébrale","q":"Quels sont les principaux mécanismes expliquant une HTIC en présence d'une tumeur cérébrale ?","a":"<ul><li><strong>Effet de masse direct</strong> de la tumeur.</li><li><strong>Œdème vasogénique</strong> péri-tumoral.</li><li><strong>Hydrocéphalie obstructive</strong> (par exemple, tumeur de fosse postérieure comprimant le ventricule 4 ou kyste colloïde du ventricule 3).</li><li><strong>Hémorragie intra-tumorale</strong>.</li></ul>"}]};